import React from "react";

const videos = [
{
title:"Waste Handling Safety",
id:"2SoH2d5wru4"
},
{
title:"Truck Operation",
id:"dBNbA80Snb8"
}
];

const TrainingTab = () => {

return(

<div className="w-full max-w-[900px]">

<h2 className="text-5xl font-black italic text-[#47510B] mb-10">
Training Modules
</h2>

<div className="grid grid-cols-2 gap-6">

{videos.map((v)=>(
<div key={v.id} className="bg-white rounded-3xl overflow-hidden shadow-lg">

<iframe
width="100%"
height="200"
src={`https://www.youtube.com/embed/${v.id}`}
title={v.title}
/>

<div className="p-4">

<h3 className="font-black text-[#47510B]">
{v.title}
</h3>

</div>

</div>
))}

</div>

</div>

);
};

export default TrainingTab;
